import sys

def min_i_to_contain_k(n, k):
    A = list(map(int, sys.stdin.readline().split()))

    def p(x):
        return [sum(x[:i+1]) for i in range(len(x))]

    i = 0
    while True:
        if any(a >= k for a in A):
            return i
        A = p([a-1 for a in A])
        i += 1

if __name__ == "__main__":
    n, k = map(int, sys.stdin.readline().split())
    result = min_i_to_contain_k(n, k)
    print(result)
